// Generated by ../rebuild.py; original lift-plan designs.
use rand::{Rng, rngs::StdRng};

struct Draft {
    shafts: usize,
    threading: Vec<usize>,
    lifts: Vec<Vec<usize>>,
    title: String,
}

#[cfg(test)]
fn drawdown(draft: &Draft) -> Vec<Vec<bool>> {
    draft
        .lifts
        .iter()
        .map(|lift| {
            draft
                .threading
                .iter()
                .map(|shaft| lift.contains(shaft))
                .collect()
        })
        .collect()
}

fn stripe_plan(rng: &mut StdRng, colors: (&str, &str)) -> String {
    let repeats: &[&[usize]] = &[
        &[1, 1],
        &[2, 2],
        &[4, 1],
        &[4, 2],
        &[1, 1, 2, 2],
        &[4, 1, 1, 1],
        &[6, 1, 1, 1],
        &[2, 1, 2, 3],
    ];
    let repeat = repeats[rng.random_range(0..repeats.len())];
    repeat
        .iter()
        .enumerate()
        .map(|(i, count)| format!("{}×{count}", if i % 2 == 0 { colors.0 } else { colors.1 }))
        .collect::<Vec<_>>()
        .join(" ")
}

fn render(rng: &mut StdRng, draft: &Draft) -> String {
    let colors = [
        ("indigo", "ivory"),
        ("charcoal", "silver"),
        ("olive", "ecru"),
        ("rust", "cream"),
        ("teal", "stone"),
        ("burgundy", "oatmeal"),
        ("ochre", "ink"),
        ("walnut", "flax"),
    ];
    let pair = colors[rng.random_range(0..colors.len())];
    let warp = stripe_plan(rng, pair);
    let weft = if rng.random_bool(0.5) {
        stripe_plan(rng, (pair.1, pair.0))
    } else {
        pair.1.to_owned()
    };
    let list = |values: &[usize]| {
        values
            .iter()
            .map(usize::to_string)
            .collect::<Vec<_>>()
            .join(" ")
    };
    let mut lines = vec![
        draft.title.clone(),
        format!("Warp {warp}"),
        format!("Weft {weft}"),
    ];
    if rng.random_bool(0.5) {
        lines.push(format!("{} shafts", draft.shafts));
        lines.push(format!("Threading {}", list(&draft.threading)));
        lines.push("Lift repeat".to_owned());
        for (i, lifted) in draft.lifts.iter().enumerate() {
            lines.push(format!("{:02}  {}", i + 1, list(lifted)));
        }
    } else {
        lines.push("Warp-over drawdown".to_owned());
        for lift in &draft.lifts {
            lines.push(
                draft
                    .threading
                    .iter()
                    .map(|shaft| if lift.contains(shaft) { 'X' } else { '.' })
                    .collect(),
            );
        }
    }
    lines.join("\n")
}

fn draft(rng: &mut StdRng) -> Draft {
    let first = rng.random_range(0..2);
    Draft {
        shafts: 2,
        threading: vec![1, 2],
        lifts: vec![vec![first + 1], vec![2 - first]],
        title: "Plain weave".to_owned(),
    }
}

pub fn generate(rng: &mut StdRng) -> String {
    let d = draft(rng);
    render(rng, &d)
}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;
    use std::collections::HashSet;

    #[test]
    fn draft_interlaces_on_both_axes_and_preserves_weave_structure() {
        let mut rng = StdRng::seed_from_u64(73);
        let mut outputs = HashSet::new();
        for _ in 0..500 {
            let d = draft(&mut rng);
            let grid = drawdown(&d);
            for row in &grid {
                assert!(row.contains(&true) && row.contains(&false));
            }
            for col in 0..d.threading.len() {
                let column: Vec<_> = grid.iter().map(|row| row[col]).collect();
                assert!(column.contains(&true) && column.contains(&false));
            }
            for &shaft in &d.threading {
                assert!((1..=d.shafts).contains(&shaft));
            }
            for lift in &d.lifts {
                assert_eq!(
                    lift.iter().copied().collect::<HashSet<_>>().len(),
                    lift.len()
                );
                assert!(lift.iter().all(|s| (1..=d.shafts).contains(s)));
            }

            assert_eq!(d.shafts, 2);
            for row in &grid {
                assert_eq!(row.iter().filter(|&&v| v).count(), 1);
            }
            for (&a, &b) in grid[0].iter().zip(&grid[1]) {
                assert_ne!(a, b);
            }

            let text = render(&mut rng, &d);
            assert!(!text.ends_with('\n'));
            outputs.insert(text);
        }
        assert!(outputs.len() >= 100);
    }
}
